CREATE TABLE gateway_oauth_clients (client_id TEXT NOT NULL PRIMARY KEY, redirect_uris_json TEXT NOT NULL, client_name TEXT, created_at INTEGER NOT NULL);
CREATE TABLE gateway_oauth_authorization_transactions (transaction_id TEXT NOT NULL PRIMARY KEY, client_id TEXT NOT NULL, redirect_uri TEXT NOT NULL, tenant_id TEXT NOT NULL, principal_id TEXT, requested_scopes_json TEXT NOT NULL, state TEXT, code_challenge TEXT NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, consumed_at INTEGER);
CREATE INDEX gateway_oauth_transactions_expiry_idx ON gateway_oauth_authorization_transactions (expires_at);
CREATE TABLE gateway_oauth_authorization_codes (code_hash TEXT NOT NULL PRIMARY KEY, client_id TEXT NOT NULL, redirect_uri TEXT NOT NULL, principal_id TEXT NOT NULL, tenant_id TEXT NOT NULL, scopes_json TEXT NOT NULL, permissions_json TEXT NOT NULL, code_challenge TEXT NOT NULL, ref_domain TEXT, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, consumed_at INTEGER);
CREATE INDEX gateway_oauth_codes_expiry_idx ON gateway_oauth_authorization_codes (expires_at);
CREATE TABLE gateway_oauth_refresh_families (family_id TEXT NOT NULL PRIMARY KEY, client_id TEXT NOT NULL, principal_id TEXT NOT NULL, tenant_id TEXT NOT NULL, created_at INTEGER NOT NULL, revoked_at INTEGER, replayed_at INTEGER);
CREATE TABLE gateway_oauth_refresh_tokens (token_hash TEXT NOT NULL PRIMARY KEY, family_id TEXT NOT NULL, generation INTEGER NOT NULL CHECK (generation >= 0), client_id TEXT NOT NULL, principal_id TEXT NOT NULL, tenant_id TEXT NOT NULL, scopes_json TEXT NOT NULL, permissions_json TEXT NOT NULL, ref_domain TEXT, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, consumed_at INTEGER, successor_hash TEXT, FOREIGN KEY (family_id) REFERENCES gateway_oauth_refresh_families (family_id));
CREATE UNIQUE INDEX gateway_oauth_refresh_generation_idx ON gateway_oauth_refresh_tokens (family_id, generation);
CREATE INDEX gateway_oauth_refresh_expiry_idx ON gateway_oauth_refresh_tokens (expires_at);
CREATE TABLE gateway_oauth_tenant_memberships (principal_id TEXT NOT NULL, tenant_id TEXT NOT NULL, scopes_json TEXT NOT NULL, ref_domain TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY (principal_id, tenant_id));
CREATE TABLE gateway_oauth_audit_events (event_id TEXT NOT NULL PRIMARY KEY, action TEXT NOT NULL, client_id TEXT NOT NULL, principal_id TEXT, tenant_id TEXT, scopes_json TEXT, reason TEXT, created_at INTEGER NOT NULL);
CREATE INDEX gateway_oauth_audit_tenant_time_idx ON gateway_oauth_audit_events (tenant_id, created_at, event_id);
